```java
import java.io.*;
import java.util.List;

public class CommandHandler {
    // Fixed: Using ProcessBuilder with a List of arguments prevents 
    // the shell from interpreting special characters like ';' or '&'.
    public void pingHost(String hostName) throws IOException {
        // By passing arguments as separate elements in a list, 
        // hostName is treated strictly as a single literal argument.
        ProcessBuilder pb = new ProcessBuilder("ping", "-c", "3", hostName);
        Process process = pb.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        CommandHandler handler = new CommandHandler();
        // Even with malicious input, 'ls -la' is treated as part of the hostname, 
        // causing the ping command to fail safely rather than executing the script.
        handler.pingHost("8.8.8.8; ls -la");
    }
}
```

